  if(margin>3)return'medium';
  return'low';
}
const _eclipseHitsBySign={};
if(eclipseAudit&&eclipseAudit.phaseA&&Array.isArray(eclipseAudit.phaseA.candidates)){
  for(const c of eclipseAudit.phaseA.candidates){
    _eclipseHitsBySign[c.sign]=Array.isArray(c.eclipsHits)?c.eclipsHits:[];
  }
}
const top3Hypotheses=signScoreMeanSorted.slice(0,3).map((entry,i)=>{
  const sign=entry[0];
  const scoreFinal=entry[1];
  const slot=(i===0&&best&&(best.ascSign===sign||best.wSign===sign))?best:bestByAsc[sign];
  const next=signScoreMeanSorted[i+1];
  const marginToNext=next?Math.round((scoreFinal-next[1])*100)/100:0;
  return{
    rank:i+1,
    sign,
    time:slot?.time||'?',
    scoreFinal:Math.round(scoreFinal*100)/100,
    scoreMean:signScoreMeanTopK[sign]!=null?Math.round(signScoreMeanTopK[sign]*100)/100:null,
    marginToNext,
    confidence:_confLabel(marginToNext),
    techBreakdown:signTechBreakdown[sign]||null,
    eclipseHits:_eclipseHitsBySign[sign]||[],
    arcScore:slot?.arcScore!=null?Math.round((slot.arcScore||0)*100)/100:null,
    progScore:slot?.progScore!=null?Math.round((slot.progScore||0)*100)/100:null,
    srScore:slot?.srScore!=null?Math.round((slot.srScore||0)*100)/100:null,
    wScore:slot?.wScore!=null?Math.round((slot.wScore||0)*100)/100:null,
    totalScore:slot?.totalScore!=null?Math.round((slot.totalScore||0)*100)/100:null
  };
});

// [v6.0] Suppression des règles v5.11.E (bascule sur qTopSign en cas d'ambiguïté) et v5.12
