// signe = pic du score total après ces correctifs ; pas de tie-break post-hoc.
const bestTime=best.time;
const hasPlanets=natalPlanets.length>0;
function sf(v){return typeof v==='number'?v.toFixed(1):v;}
function sfq(v){return (typeof v==='number'&&Number.isFinite(v))?Number(v.toFixed(2)):v;}
const te=(best.arcScore||0)+(best.progScore||0)+(best.srScore||0);
let method='';
// [i18n v5.5] `method` est construit plus bas, après l'initialisation du helper T() (besoin de vars.langue).

const windowGroups={};
for(const d of cleanDetail){
  const wk=d.wSign||d.ascSign||'?';
  if(!windowGroups[wk])windowGroups[wk]={sign:wk,score:d.wScore,items:[]};
  else windowGroups[wk].score=Math.max(windowGroups[wk].score,d.wScore);
  windowGroups[wk].items.push(d);
}

const nAnalysed=validDetail.length;
const gridFull=nAnalysed>=280;
let scanMetaNote='';
// scanMetaNote est construit après le helper T() (défini juste en dessous) et utilise donc T('scorerMeta', …).
// Initialisation à '' ici ; remplissage dans un second try/catch immédiatement après l'initialisation de T.
// [i18n v5.5] Détection langue de sortie depuis Extract Variables (vars.langue = "Français" | "English").
