const toT=m=>pad(Math.floor(m/60))+':'+pad(m%60);
const trans=[];for(let i=0;i<23;i++){if(hourly[i].s!==hourly[i+1].s)trans.push(i+1)}
const bds=[0,...trans.map(t=>t*60),1440];
